# socket_test_loopback.py
import socket
import json
import time
import threading

# Use local loopback to simulate Codex (WinUI) and Antigravity (APK) locally
HOST = "127.0.0.1"
PORT = 8080

def run_apk_server():
    """Simulates the Android Companion APK TCP server generated by Antigravity."""
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((HOST, PORT))
    server.listen(1)
    print("[AGY APK Server] Listening on {}:{}...".format(HOST, PORT))
    
    conn, addr = server.accept()
    print("[AGY APK Server] WinUI Client connected from {}".format(addr))
    
    try:
        # 1. Receive Handshake from WinUI Client
        raw_handshake = conn.recv(1024).decode('utf-8')
        if not raw_handshake:
            return
        handshake_data = json.loads(raw_handshake)
        print("[AGY APK Server] Received: {}".format(json.dumps(handshake_data, indent=2)))
        
        # 2. Send Authorization Response back
        response = {
            "type": "HANDSHAKE_RESPONSE",
            "status": "AUTHORIZED",
            "device_name": "Google Pixel 10 (Mock Loopback)"
        }
        conn.sendall(json.dumps(response).encode('utf-8'))
        print("[AGY APK Server] Handshake Authorization sent.")
        
        # 3. Simulate streaming an Interactive Notification Enqueue payload
        time.sleep(1.5)
        notification_event = {
            "event_type": "NOTIFICATION_ENQUEUE",
            "timestamp": int(time.time()),
            "data": {
                "notification_id": 4012,
                "package_name": "com.google.android.apps.messaging",
                "app_label": "Messages",
                "title": "Tara Sheridan Qualey",
                "body": "Hey Austin! Did you finish syncing the GitHub repo?",
                "icon_base64": "iVBORw0KGgoAAAANSUhEUgAAAEAAAABACAYAAACqaXHe..."
            }
        }
        conn.sendall(json.dumps(notification_event).encode('utf-8'))
        print("[AGY APK Server] Simulated Notification sent to WinUI.")
        
        # 4. Wait for WinUI Quick Reply response
        raw_reply = conn.recv(1024).decode('utf-8')
        if raw_reply:
            reply_data = json.loads(raw_reply)
            print("[AGY APK Server] Received Reply Payload from WinUI Client:")
            print(json.dumps(reply_data, indent=2))
            
    except Exception as e:
        print("[AGY APK Server] Error: {}".format(e))
    finally:
        conn.close()
        server.close()

def run_winui_client():
    """Simulates the Windows WinUI 3 desktop client generated by Codex."""
    time.sleep(0.5) # Allow server thread to establish port binding
    print("[Codex WinUI Client] Connecting to APK Server at {}:{}...".format(HOST, PORT))
    
    client = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        client.connect((HOST, PORT))
        
        # 1. Send Handshake Initiation
        handshake_init = {
            "type": "HANDSHAKE_INIT",
            "version": "1.0.0",
            "timestamp": int(time.time()),
            "payload": {
                "secret_key_b64": "U01BUlRfTUlSUk9SX0FFU19HQ01fMjU2X0tFWV9TQU1QTEU="
            }
        }
        client.sendall(json.dumps(handshake_init).encode('utf-8'))
        print("[Codex WinUI Client] Handshake initiation sent.")
        
        # 2. Read Auth Status Response
        raw_auth = client.recv(1024).decode('utf-8')
        auth_data = json.loads(raw_auth)
        print("[Codex WinUI Client] Received Auth: {}".format(json.dumps(auth_data, indent=2)))
        
        # 3. Listen for incoming Notification stream payload
        raw_notification = client.recv(2048).decode('utf-8')
        if raw_notification:
            notification_data = json.loads(raw_notification)
            print("[Codex WinUI Client] Incoming notification received from phone:")
            print(json.dumps(notification_data, indent=2))
            
            # 4. Simulate a Quick Reply submission
            time.sleep(1)
            reply_payload = {
                "event_type": "NOTIFICATION_REPLY",
                "timestamp": int(time.time()),
                "data": {
                    "notification_id": 4012,
                    "package_name": "com.google.android.apps.messaging",
                    "reply_text": "Yeah, Codex and Antigravity matched up the contract files perfectly!"
                }
            }
            client.sendall(json.dumps(reply_payload).encode('utf-8'))
            print("[Codex WinUI Client] Quick Reply message sent back to phone.")
            
    except Exception as e:
        print("[Codex WinUI Client] Error: {}".format(e))
    finally:
        client.close()

if __name__ == "__main__":
    print("=== STARTING ARCHITECTURE CONTRACT LOOPBACK TEST ===")
    server_thread = threading.Thread(target=run_apk_server)
    client_thread = threading.Thread(target=run_winui_client)
    
    server_thread.start()
    client_thread.start()
    
    server_thread.join()
    client_thread.join()
    print("=== LOOPBACK TEST COMPLETED SUCCESSFULLY ===")
